namespace EggPdf.Tests.Unit.Pdf;

/// <summary>
/// Lossy WebP files encoded by Chrome's canvas.toDataURL("image/webp") together with the RGBA pixels
/// Chrome itself decoded them to (getImageData): the ground truth the VP8 decoder is checked against.
/// </summary>
internal static class WebPLossyFixtures
{
    internal readonly struct Fixture
    {
        public readonly string Name; public readonly int Width, Height; public readonly string WebPBase64, RgbaBase64;
        public Fixture(string name, int w, int h, string webp, string rgba) { Name = name; Width = w; Height = h; WebPBase64 = webp; RgbaBase64 = rgba; }
    }

    public static readonly Fixture Lossy33x21 = new Fixture("lossy33x21", 33, 21,
        "",
        "");

    public static readonly Fixture Lossy48x32 = new Fixture("lossy48x32", 48, 32,
        "",
        "");

    public static readonly Fixture Lossy64x40lowq = new Fixture("lossy64x40lowq", 64, 40,
        "",
        "");

    public static readonly Fixture Lossy100x70 = new Fixture("lossy100x70", 100, 70,
        "",
        "");

    public static readonly Fixture Alpha40x30 = new Fixture("alpha40x30", 40, 30,
        "",
        "");

    public static readonly Fixture Alpha17x13 = new Fixture("alpha17x13", 17, 13,
        "",
        "");

    public static readonly Fixture[] All = { Lossy33x21, Lossy48x32, Lossy64x40lowq, Lossy100x70, Alpha40x30, Alpha17x13 };
}
